using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "TwinSmashCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Cellarius/TwinSmashCustomDescription", order = 0)]
public class TwinSmashCustomDescription : CustomBattleActionDescription
{
	[SerializeField]
	private PurifyCorruptCustomDescription purifyCorruptCustomDescription;

	[SerializeField]
	private bool purify;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		PurifyCorruptXTimesAction purifyCorruptXTimesAction = battleAction as PurifyCorruptXTimesAction;
		string localizedString = base.localizationManager.GetLocalizedString(purify ? "Purify_D" : "Corrupt_D");
		localizedString = Smart.Format(purifyCorruptCustomDescription.GetTargetCorruptPurifyLocalized(battleAction).RemoveLast(), Smart.Format(localizedString, GetFinalAmountWithoutEquation(amountModified)));
		return base.localizationManager.GetLocalizedXTimesFormatted(localizedString, purifyCorruptXTimesAction.GetTimesAmount().Item1, purifyCorruptXTimesAction.GetTimesAmount().Item2);
	}
}
